async function save(e:any,keepOpen=false,emit=false,confirmKickoff=false){e.preventDefault();if(!edit)return;if(document.querySelector('[data-uploading="true"]')){setError('Espera a que terminen de cargarse las imágenes y los anexos antes de guardar.');return;}setBusy(true);setError('');try{let record={...edit};if(record.kind==='travel')record.amount=Number(record.people)*Number(record.days)*Number(record.rate);if(record.kind==='quote'){record.wizardVersion=1;if(confirmKickoff)record._confirmKickoff=true;const problem=emit?pricingError(record,true):record.status==='Borrador'?draftPricingError(record):pricingError(record);if(problem)throw Error(problem);if(emit){if(!record.budgetReviewed)throw Error('Revisa el presupuesto en la página 3 antes de emitir.');if(!record.validUntil||!record.terms?.trim()||!record.generalTerms?.trim())throw Error('Completa vigencia, condiciones de pago y términos comerciales.');if(record.status==='Borrador')record.status='Emitida';}delete record._page;}if(record.kind==='concept')record.name=record.item?.description;if(record.kind==='payment'){const src=rows.find(r=>r.id===record.sourceId);if(!src)throw Error('Selecciona la solicitud o campamento relacionado.');if(src.kind==='travel'&&!['Autorizada','En cierre','Cerrada'].includes(src.status))throw Error('La solicitud debe estar autorizada antes de registrar una entrega.');if(src.kind==='camp'&&!record.period)throw Error('Indica el periodo de renta.');record.projectId=src.projectId;record.division=src.division;record.type=src.kind==='camp'?'Renta':'Viáticos';if(Number(record.amount)<=0)throw Error('El importe debe ser mayor a cero.');if(src.kind==='travel'&&paid(src.id)-(edit.revision?Number(rows.find(r=>r.id===edit.id)?.amount||0):0)+Number(record.amount)>Number(src.amount))throw Error('La entrega supera el importe autorizado.');}
const res=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});const d:any=await res.json();if(!res.ok)throw Error(d.error);setDetail(null);const refreshed=await load();if(keepOpen){const saved=refreshed?.find((r:R)=>r.id===record.id);setEdit({...((saved||{...d.record,revision:Number(edit.revision||0)+1})),_page:edit._page||1});}else{setEdit(null);if(record.kind==='candidate')setDetail(refreshed?.find((r:R)=>r.id===record.id)||null);if(emit&&!d.project)setDetail(refreshed?.find((r:R)=>r.id===record.id)||null);}if(d.project)setHub(refreshed?.find((r:R)=>r.id===d.project.id)||d.project);setToast(d.project?'Proyecto listo · '+d.requisitions+' requisiciones nuevas enviadas a Reclutamiento':confirmKickoff?'Kickoff comercial registrado':emit?'Cotización emitida · Lista para descargar en PDF':keepOpen?'Borrador guardado · Puedes continuar':'Registro guardado');setTimeout(()=>setToast(''),3000)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
