function renderExtraFields(){if(!edit)return null;const primary:Record<string,string[]>={employee:['position','start','fileStatus','missingDocuments','induction','campId','dailyRate'],candidate:['recruitmentId','phone','labDate','labResult','transferDate','incorporatedDate'],operation:['activityType','responsible','start','end','progress','scope'],commercial:['activityType','responsible','due','amount','document','clientApproval'],development:['activityType','employeeId','start','expiry','score','evidence']};const fields=extraFields[edit.kind]||[];const render=(f:any)=>input(f.key,f.label,f.type||'text',!!f.required,f.ref?list(f.ref).filter(r=>(!edit.projectId||!['recruitment','candidate','employee','camp'].includes(f.ref)||r.projectId===edit.projectId)&&(!edit.recruitmentId||f.ref!=='candidate'||r.recruitmentId===edit.recruitmentId)):f.options?f.options.map((v:string)=>({id:v,name:v})):undefined);const base=primary[edit.kind];if(!base)return fields.map(render);return <>{fields.filter(f=>base.includes(f.key)||f.required).map(render)}<details className="additionalFields"><summary>Más detalles (opcional)</summary><div className="formgrid">{fields.filter(f=>!base.includes(f.key)&&!f.required).map(render)}</div></details></>}
function recordPayment(source:R){fresh('payment');setEdit(prev=>({...prev!,sourceId:source.id,projectId:source.projectId,division:source.division,amount:source.kind==='travel'?Math.max(0,Number(source.amount)-paid(source.id)):Math.max(0,Number(source.amount)-list('payment').filter(p=>p.sourceId===source.id&&p.period===source.due?.slice(0,7)).reduce((a,p)=>a+Number(p.amount),0)),period:source.kind==='camp'?source.due?.slice(0,7):'',date:today(),status:'Pagado'}));}
function nextActions(r:R){if(!writableRecord(r))return [];const actions:{label:string,status:string}[]=workflowActions(r);if(r.kind==='recruitment'&&['Solicitada','Publicada','En selección'].includes(r.status))actions.push({label:'Cancelar vacante',status:'Cancelada'});const admin=['Administrador','Dirección'].includes(role);if(r.kind==='quote'){if(['En revisión','Autorizada','Emitida'].includes(r.status)||r.status==='Borrador'&&!r.wizardVersion)actions.push({label:r.status==='Emitida'?'Registrar envío al cliente':'Enviar cotización',status:'Enviada'});if(r.status==='Enviada')actions.push({label:'Iniciar negociación',status:'En negociación'});if(r.status==='En negociación')actions.push({label:'Cerrar ganada y abrir proyecto',status:'Aceptada'},{label:'Cerrar declinada',status:'Declinada'},{label:'Cerrar perdida',status:'Perdida'});}if(r.kind==='transfer'){const next=({Solicitada:admin?'Autorizada':null,Autorizada:'Programada',Programada:'Realizada'} as R)[r.status];if(next)actions.push({label:next==='Autorizada'?'Autorizar traslado':next==='Programada'?'Programar traslado':'Confirmar llegada',status:next});}if(r.kind==='travel'){if(['Borrador','Solicitada'].includes(r.status))actions.push({label:'Cancelar solicitud',status:'Cancelada'});if(['Solicitada','Visto bueno RH'].includes(r.status)&&(admin||role==='Recursos Humanos'))actions.push({label:'Rechazar solicitud',status:'Rechazada'});if(r.status==='Borrador')actions.push({label:'Enviar solicitud',status:'Solicitada'});if(r.status==='Solicitada'&&(admin||role==='Recursos Humanos'))actions.push({label:'Dar visto bueno RH',status:'Visto bueno RH'});if(r.status==='Visto bueno RH'&&admin)actions.push({label:'Autorizar viáticos',status:'Autorizada'});if(r.status==='Autorizada'&&(admin||role==='Recursos Humanos'))actions.push({label:'Preparar comprobación o acuse',status:'En cierre'});if(r.status==='En cierre'&&(admin||role==='Recursos Humanos'))actions.push({label:'Revisar y cerrar',status:'Cerrada'});}if(r.kind==='program'){if(r.status==='Autorizado')actions.push({label:'Cerrar programa',status:'Cerrado'});if(['Borrador','En revisión'].includes(r.status))actions.push({label:'Cancelar programa',status:'Cancelado'});if(r.status==='Borrador')actions.push({label:'Enviar a autorización',status:'En revisión'});if(r.status==='En revisión'&&admin)actions.push({label:'Autorizar programa',status:'Autorizado'});}if(r.kind==='recruitExpense'){if(r.status==='Previsto'&&admin)actions.push({label:'Autorizar gasto',status:'Autorizado'});if(r.status==='Autorizado'&&(admin||role==='Tesorería'))actions.push({label:'Registrar pago',status:'Pagado'});}if(r.kind==='candidate'){if(!['Incorporado','Descartado'].includes(r.status))actions.push({label:'Descartar candidato',status:'Descartado'});const next=({Postulado:'Entrevista',Entrevista:'Laboratorio',Laboratorio:'Apto',Apto:null,Traslado:null} as R)[r.status];if(next)actions.push({label:next==='Incorporado'?(r.status==='Apto'?'Incorporar sin traslado':'Confirmar incorporación'):next==='Laboratorio'?'Programar laboratorio':next==='Traslado'?'Programar traslado':'Pasar a '+next,status:next});}return actions;}
async function advance(r:R,status:string){if(r.kind==='quote'&&status==='Aceptada'){fromQuote(r);return;}if(['candidate','recruitExpense','requirement'].includes(r.kind)||r.kind==='employee'&&status==='Inactivo'||r.kind==='travel'&&status==='Cerrada'){setEdit({...r,status,...(status==='Incorporado'?{incorporatedDate:today()}:{})});setError('');return;}setBusy(true);setError('');try{const res=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...r,status})});const d:any=await res.json();if(!res.ok)throw Error(d.error);const refreshed=await load();setDetail(refreshed?.find((v:R)=>v.id===r.id)||null);setToast('Actualizado: '+status);setTimeout(()=>setToast(''),3000)}catch(e:any){setError(e.message)}finally{setBusy(false)}}

